<div class="amp-stage"><div id="amp-canvas"></div><div class="amp-stage-label"><b>Inverting amplifier</b><span id="circuit-status">Supply off · 0 leads</span></div><div class="amp-stage-tools"><details class="amp-connection-tools"><summary>Connection tools</summary><div class="amp-connect-bar"><div class="amp-endpoints"><label>From<select id="from">${Fe()}</select></label><span aria-hidden="true">→</span><label>To<select id="to">${Fe()}</select></label><button data-do="connect" class="primary">Connect</button></div><div class="amp-probe-connect"><label>Instrument<select id="probe"><option value="">Choose probe…</option>${Object.entries(ae).map(([e,n])=>`<option value="${e}">${n}</option>`).join("")}</select></label><label>At<select id="probe-target">${Fe()}</select></label><button data-do="probe">Place</button><button data-do="disconnect" aria-label="Disconnect selected probe">Unplug</button></div></div></details><button data-do="rotate" id="rotate" aria-pressed="false">Rotate view</button><button data-do="home">Home view</button><button data-do="board-view" class="amp-phone-only">Board close-up</button><button data-do="leads">Select lead</button><button data-do="scope" id="scope-desktop">Hold scope</button></div><div class="amp-stage-help">Drag cable to reshape · Drag plug to reconnect · Esc cancels</div><div class="amp-pending-connection" hidden><span id="pending-endpoints"></span><button data-do="connect" class="primary" id="pending-connect">Connect</button><button data-do="cancel-selection" aria-label="Cancel terminal selection">×</button></div><div class="amp-lead-inspector" hidden><label>Lead<select id="lead-list" aria-label="Select a circuit lead"></select></label><strong id="selected-lead"></strong><button data-do="remove">Remove</button><button data-do="close-leads" aria-label="Close lead inspector">×</button></div></div>
